const copy={
en:{captureTag:'ACTUAL ENGINE CAPTURE',nav:['The contract','Inside Ignis','The horizon','The evidence'],eyebrow:'04 / THE ENGINE BEHIND THE SPARK',title:'Every detail.<br><em>MCP first.</em>',intro:'AI can control the entire engine. By design.',manifesto:'Create a scene. Configure a sense. Cast an ability. Inspect a decision. Reproduce a failure. Every controllable detail belongs in MCP before, or alongside, its visual control. This is the architecture of Ignis — and the rule for every system still to come.',human:'Human intent',agent:'AI agent',shared:'ONE SHARED CONTRACT',runtime:'RUST / 3D RUNTIME',stages:['Create','Run','Observe','Refine','Verify'],stageNotes:['Generate a seeded room from a recipe.','Advance a paused simulation by exactly 120 ticks.','Inspect NPC state and the reasons behind decisions.','Reverse the last authored edit as one transaction.','Run a saved scenario with typed checks and a finite budget.'],example:'CONTRACT EXAMPLE · NOT EXECUTED ON THIS PAGE',principles:['Same project. Same API.','No AI vendor lock-in.','Your game runs without its agent.'],atlasSmall:'05 / SYSTEMS ALREADY IMPLEMENTED',atlasTitle:'Under the<br><em>surface.</em>',atlasIntro:'A growing engine, already full of systems that interact. Open a layer. Follow the contract. See where the current implementation ends.',filters:['All systems','World','Minds & movement','Actions & effects','Evidence'],search:'Find a capability',results:'systems',limit:'CURRENT BOUNDARY',commands:'MCP OPERATIONS',inventory:'Explore 56 documented command examples',empty:'No matching systems. Try another term.',roadSmall:'06 / THE COMPLETE ROADMAP',roadTitle:'A spark is<br>only <em>the start.</em>',roadIntro:'Sixteen connected domains. One rule: everything remains observable, procedural where relevant, and controllable through MCP. Explore the whole ambition.',roadNote:'Domains, not release dates. This atlas preserves an early content snapshot; see GitHub for current implementation and limits.',now:'IMPLEMENTED FOUNDATION',next:'THE REMAINING HORIZON',planned:'Planned system. Implementation is still ahead.',partial:'FOUNDATIONS IN PLACE',future:'PLANNED',focus:'EARLY SNAPSHOT FOCUS',proofSmall:'07 / REAL ENGINE. REAL BOUNDARIES.',proofTitle:'Built to be<br><em>understood.</em>',proofBody:'The laboratory is deliberately simple to look at. The systems underneath are not. This is an actual capture from Ignis, with perception guides — separate from the conceptual web scene above.',facts:['Rust core. Native 3D.','macOS / Metal validated first.','Versioned scenes. Reversible authorship.','Headless scenarios. Inspectable replay.'],proofNote:'Source available under the Ignis commercial license. After USD 1M lifetime Game revenue, royalties are 1% of eligible profit. Read the terms and current limits on GitHub.',source:'Capability atlas: 24 OCT 2026 snapshot. Current source, setup and limitations: GitHub.',graphLabel:'Human and AI share the same command dispatcher and Rust engine.',roadLabel:'Choose a roadmap domain',loop:'DESCRIBE → BUILD → PLAY → OBSERVE → REFINE'},
pt:{captureTag:'CAPTURA REAL DA ENGINE',nav:['O contrato','Dentro da Ignis','O horizonte','A evidência'],eyebrow:'04 / A ENGINE POR TRÁS DA CENTELHA',title:'Cada detalhe.<br><em>MCP first.</em>',intro:'A IA pode controlar a engine inteira. Por arquitetura.',manifesto:'Crie uma cena. Configure um sentido. Lance uma habilidade. Inspecione uma decisão. Reproduza uma falha. Cada detalhe controlável precisa existir no MCP antes, ou junto, do controle visual. Essa é a arquitetura da Ignis — e a regra para todos os sistemas que ainda virão.',human:'Intenção humana',agent:'Agente de IA',shared:'UM CONTRATO COMPARTILHADO',runtime:'RUST / RUNTIME 3D',stages:['Criar','Executar','Observar','Refinar','Verificar'],stageNotes:['Gere uma sala a partir de receita e semente.','Avance uma simulação pausada em exatamente 120 ticks.','Inspecione o estado dos NPCs e os motivos das decisões.','Reverta a última edição autoral como uma transação.','Execute um cenário salvo, com checks tipados e orçamento finito.'],example:'EXEMPLO DO CONTRATO · NÃO EXECUTADO NESTA PÁGINA',principles:['Mesmo projeto. Mesma API.','Sem dependência de fornecedor de IA.','Seu jogo executa sem o agente.'],atlasSmall:'05 / SISTEMAS JÁ IMPLEMENTADOS',atlasTitle:'Por baixo da<br><em>superfície.</em>',atlasIntro:'Uma engine em evolução, já cheia de sistemas que interagem. Abra uma camada. Siga o contrato. Veja até onde a implementação atual vai.',filters:['Todos os sistemas','Mundo','Mentes e movimento','Ações e efeitos','Evidência'],search:'Encontre uma capacidade',results:'sistemas',limit:'LIMITE ATUAL',commands:'OPERAÇÕES MCP',inventory:'Explore 56 exemplos documentados de comandos',empty:'Nenhum sistema encontrado. Tente outro termo.',roadSmall:'06 / O ROADMAP COMPLETO',roadTitle:'A centelha é<br>só <em>o começo.</em>',roadIntro:'Dezesseis domínios conectados. Uma regra: tudo observável, procedural onde fizer sentido e controlável pelo MCP. Explore a ambição inteira.',roadNote:'Domínios, não datas de lançamento. Este atlas preserva um retrato inicial; veja no GitHub a implementação e os limites atuais.',now:'FUNDAMENTO IMPLEMENTADO',next:'O HORIZONTE QUE FALTA',planned:'Sistema planejado. A implementação ainda está adiante.',partial:'FUNDAMENTOS PRESENTES',future:'PLANEJADO',focus:'FOCO DO RETRATO INICIAL',proofSmall:'07 / ENGINE REAL. LIMITES REAIS.',proofTitle:'Feita para ser<br><em>compreendida.</em>',proofBody:'O laboratório tem uma aparência deliberadamente simples. Os sistemas por baixo dele, não. Esta é uma captura real da Ignis, com guias de percepção — separada da composição web conceitual acima.',facts:['Núcleo Rust. 3D nativo.','macOS / Metal validado primeiro.','Cenas versionadas. Autoria reversível.','Cenários headless. Replay inspecionável.'],proofNote:'Código disponível sob licença comercial Ignis. Após US$1M de receita por jogo, participação de 1% do lucro elegível. Leia os termos e limites no GitHub.',source:'Atlas de capacidades: retrato de 24 OUT 2026. Código, início e limites atuais: GitHub.',graphLabel:'Humano e IA compartilham o mesmo dispatcher de comandos e engine Rust.',roadLabel:'Escolha um domínio do roadmap',loop:'DESCREVER → CONSTRUIR → JOGAR → OBSERVAR → REFINAR'}
};
const examples=[{op:'generate',recipe:{width:16,depth:14,seed:42,obstacles:4}},{op:'step',ticks:120},{op:'inspect_npcs'},{op:'undo'},{op:'run_scenario',path:'examples/quiet.scenario.json'}];
const rootSystems=[
 {id:'combat',name:['Combat','Combate'],symbol:'⌖',members:[13,14,15,16]},
 {id:'npcs',name:['NPCs','NPCs'],symbol:'◎',members:[5,6,7,8,9,10,11,12,13]},
 {id:'character',name:['Character','Personagem'],symbol:'↟',members:[2,12,13,14]},
 {id:'world',name:['World','Mundo'],symbol:'◇',members:[0,1,4]},
 {id:'render',name:['Rendering','Renderização'],symbol:'◈',members:[3,18]},
 {id:'tools',name:['Tools','Ferramentas'],symbol:'⌘',members:[1,17,18,19]},
 {id:'all',name:['Everything','Tudo'],symbol:'✳',members:systems.map((_,i)=>i)}
];
export function mountEngineChapters(onLayout){
 const root=document.getElementById('engine-chapters');let lang='en',idx=0,stage=0,selected=8,filter='combat',query='';
 const t=x=>x[idx];const esc=x=>x.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 root.innerHTML=`<nav class="engine-nav" aria-label="Engine"><a href="#protocol"></a><a href="#capabilities"></a><a href="#roadmap"></a><a href="#engine-proof"></a></nav><section id="protocol" class="protocol engine-pad"><div class="engine-kicker" data-e="eyebrow"></div><h2 class="engine-mega" data-eh="title"></h2><div class="protocol-intro"><h3 data-e="intro"></h3><p data-e="manifesto"></p></div><div class="command-theatre"><div class="contract-graph" role="img"><svg viewBox="0 0 600 360" aria-hidden="true"><defs><radialGradient id="coreGlow"><stop stop-color="#ff603a" stop-opacity=".28"/><stop offset="1" stop-color="#ff603a" stop-opacity="0"/></radialGradient></defs><circle cx="300" cy="180" r="175" fill="url(#coreGlow)"/><g class="graph-orbits"><ellipse cx="300" cy="180" rx="175" ry="115"/><ellipse cx="300" cy="180" rx="115" ry="175"/><circle cx="300" cy="180" r="83"/></g><path class="graph-track" d="M20 60H140L250 150M580 60H460L350 150M300 210V330"/><path class="graph-flow" d="M20 60H140L250 150M580 60H460L350 150M300 210V330"/><circle class="graph-core" cx="300" cy="180" r="42"/><text x="300" y="189" text-anchor="middle">✳</text></svg><span class="graph-human" data-e="human"></span><span class="graph-agent" data-e="agent"></span><span class="graph-contract" data-e="shared"></span><span class="graph-runtime" data-e="runtime"></span></div><div class="command-console"><div class="stage-controls" role="group"></div><p class="stage-note"></p><pre tabindex="0"><code></code></pre><p class="example-note" data-e="example"></p></div></div><div class="protocol-principles"></div><div class="engine-loop" data-e="loop"></div></section><section id="capabilities" class="capabilities engine-pad"><div class="engine-kicker" data-e="atlasSmall"></div><div class="engine-heading"><h2 data-eh="atlasTitle"></h2><p data-e="atlasIntro"></p></div><div class="root-tabs-scroll"><div class="atlas-filters root-tabs" role="tablist"></div></div><div class="atlas-tools"><label class="atlas-search"><span data-e="search"></span><input type="search" maxlength="120"></label></div><div class="atlas-count" role="status" aria-live="polite"></div><div class="system-list" id="root-system-panel" role="tabpanel" tabindex="0"></div><p class="atlas-empty" hidden data-e="empty"></p><details class="command-inventory"><summary data-e="inventory"></summary><div>${operations.map(op=>`<code>${op}</code>`).join('')}</div></details></section><section id="roadmap" class="roadmap engine-pad"><div class="engine-kicker" data-e="roadSmall"></div><div class="engine-heading"><h2 data-eh="roadTitle"></h2><p data-e="roadIntro"></p></div><div class="roadmap-workspace"><div class="roadmap-map"><svg viewBox="0 0 400 400" preserveAspectRatio="none" aria-hidden="true"><path d="M50 50H350V150H50V250H350V350H50M50 50V350M150 50V350M250 50V350M350 50V350"/></svg><div class="roadmap-nodes" role="group"></div></div><article class="roadmap-detail" aria-live="polite"></article></div><p class="roadmap-note" data-e="roadNote"></p></section><section id="engine-proof" class="engine-proof engine-pad"><div class="engine-kicker" data-e="proofSmall"></div><div class="engine-heading"><h2 data-eh="proofTitle"></h2><p data-e="proofBody"></p></div><div class="proof-evidence"><figure><div class="capture-toolbar micro"><span>IGNIS / MCP</span><span data-e="captureTag">ACTUAL ENGINE CAPTURE</span></div><img src="assets/laboratory.webp" data-alt="captureAlt" alt="Ignis perception laboratory" width="1280" height="900" loading="lazy"><figcaption>PERCEPTION LAB / macOS / Metal</figcaption></figure><div class="proof-facts"></div></div><p class="engine-boundary" data-e="proofNote"></p><p class="content-snapshot" data-e="source"></p></section>`;
 const $=s=>root.querySelector(s);
 function renderStage(){const d=copy[lang];$('.stage-controls').innerHTML=d.stages.map((x,i)=>`<button aria-pressed="${stage===i}" data-stage="${i}"><span>0${i+1}</span>${x}</button>`).join('');$('.stage-note').textContent=d.stageNotes[stage];$('pre code').textContent=JSON.stringify({tool:'engine_command',arguments:{command:examples[stage]}},null,2);}
 function renderRoad(){const d=copy[lang],r=roadmap[selected];$('.roadmap-nodes').innerHTML=roadmap.map((r,i)=>`<button data-road="${i}" aria-pressed="${i===selected}" class="${i===8?'current-focus':''}"><span>${r.id}${i===8?' ↗':''}</span><strong>${esc(t(r.title))}</strong><i class="${r.now[0]?'partial':'planned'}"></i></button>`).join('');$('.roadmap-nodes').setAttribute('aria-label',d.roadLabel);$('.roadmap-detail').innerHTML=`<div class="road-detail-top"><span>${r.id} / 16</span><span>${selected===8?d.focus:r.now[0]?d.partial:d.future}</span></div><h3>${esc(t(r.title))}</h3><div class="road-detail-now"><span>${d.now}</span><p>${esc(t(r.now)||d.planned)}</p></div><div class="road-detail-next"><span>${d.next}</span><p>${esc(t(r.next))}</p></div>`;onLayout();}
 function applyFilter(){const q=query.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();let count=0;root.querySelectorAll('.system-row').forEach((row,i)=>{const s=systems[i];const visible=rootSystems.find(g=>g.id===filter).members.includes(i)&&(!q||row.dataset.search.includes(q));row.hidden=!visible;if(visible){row.style.setProperty('--row-order',String(count));count++;}});$('.atlas-count').textContent=`${String(count).padStart(2,'0')} / 20 ${copy[lang].results}`;$('.atlas-empty').hidden=count!==0;root.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===filter;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});$('.system-list').setAttribute('aria-labelledby',`root-tab-${filter}`);onLayout();}
 function renderSystems(open){depthObserver.disconnect();releaseSurface();const d=copy[lang];$('.system-list').innerHTML=systems.map((s,i)=>`<details class="system-row" ${open.has(i)?'open':''} data-search="${esc((t(s.title)+' '+t(s.body)+' '+t(s.limit)+' '+s.commands.join(' ')).normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase())}"><summary><span class="system-glyph" aria-hidden="true"><svg viewBox="0 0 120 120"><g transform="rotate(${i*17} 60 60)"><ellipse cx="60" cy="60" rx="48" ry="19"/><ellipse cx="60" cy="60" rx="19" ry="48"/><path d="M60 7 106 33 106 87 60 113 14 87 14 33ZM60 7V113M14 33 106 87M106 33 14 87M14 33 60 60 106 33M14 87 60 60 106 87"/><circle cx="60" cy="60" r="31"/></g></svg></span><span class="system-number">${String(i+1).padStart(2,'0')}</span><h3>${esc(t(s.title))}</h3><span class="system-toggle" aria-hidden="true">↗</span></summary><div class="system-content"><p>${esc(t(s.body))}</p><div class="system-boundary"><span>${d.limit}</span><p>${esc(t(s.limit))}</p></div><div class="operation-chips"><span>${d.commands}</span>${s.commands.map(x=>`<code>${x}</code>`).join('')}</div></div></details>`).join('');applyFilter();}
 function translate(next){const open=new Set([...root.querySelectorAll('.system-row')].flatMap((r,i)=>r.open?[i]:[]));lang=next==='pt'?'pt':'en';idx=lang==='pt'?1:0;const d=copy[lang];$('.contract-graph').setAttribute('aria-label',d.graphLabel);$('.stage-controls').setAttribute('aria-label',lang==='pt'?'Ciclo de comandos':'Command cycle');root.querySelectorAll('[data-e]').forEach(n=>n.textContent=d[n.dataset.e]);root.querySelectorAll('[data-eh]').forEach(n=>n.innerHTML=d[n.dataset.eh]);root.querySelectorAll('.engine-nav a').forEach((a,i)=>a.textContent=d.nav[i]);$('.engine-nav').setAttribute('aria-label',lang==='pt'?'Explore a engine':'Explore the engine');$('.atlas-filters').setAttribute('aria-label',lang==='pt'?'Sistemas da engine':'Engine systems');$('.atlas-filters').innerHTML=rootSystems.map((g,i)=>`<button id="root-tab-${g.id}" role="tab" data-filter="${g.id}" aria-selected="${filter===g.id}" aria-controls="root-system-panel" tabindex="${filter===g.id?0:-1}"><span class="root-tab-face"><span class="root-tab-top"><span>${String(i+1).padStart(2,'0')}</span><span aria-hidden="true">${g.symbol}</span></span><strong>${esc(t(g.name))}</strong><span class="root-tab-bottom"><span>${String(g.members.length).padStart(2,'0')}</span><span aria-hidden="true">↗</span></span></span></button>`).join('');$('.protocol-principles').innerHTML=d.principles.map((x,i)=>`<p><span>0${i+1} /</span>${esc(x)}</p>`).join('');$('.proof-facts').innerHTML=d.facts.map((x,i)=>`<p><span>0${i+1}</span>${esc(x)}</p>`).join('');$('.proof-evidence figcaption').textContent=lang==='pt'?'LABORATÓRIO DE PERCEPÇÃO / macOS / Metal':'PERCEPTION LABORATORY / macOS / Metal';renderStage();renderSystems(open);root.querySelectorAll('.system-row').forEach(row=>depthObserver.observe(row));renderRoad();}
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.stage!==undefined){stage=Number(b.dataset.stage);renderStage();$('.stage-controls').querySelector(`[data-stage="${stage}"]`).focus({preventScroll:true});onLayout();}if(b.dataset.filter){filter=b.dataset.filter;applyFilter();}if(b.dataset.road!==undefined){selected=Number(b.dataset.road);renderRoad();$('.roadmap-nodes').querySelector(`[data-road="${selected}"]`).focus({preventScroll:true});}});
 root.addEventListener('keydown',e=>{const tab=e.target.closest('[data-filter]');if(tab){const i=rootSystems.findIndex(g=>g.id===tab.dataset.filter),delta={ArrowRight:1,ArrowLeft:-1}[e.key];if(delta!==undefined||e.key==='Home'||e.key==='End'){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?rootSystems.length-1:(i+delta+rootSystems.length)%rootSystems.length;filter=rootSystems[next].id;applyFilter();const target=$(`[data-filter="${filter}"]`);target.focus({preventScroll:true});target.scrollIntoView({block:'nearest',inline:'nearest',behavior:'instant'});}return;}const b=e.target.closest('[data-road]');if(!b)return;const delta={ArrowRight:1,ArrowLeft:-1,ArrowDown:4,ArrowUp:-4}[e.key];if(delta!==undefined||e.key==='Home'||e.key==='End'){e.preventDefault();selected=e.key==='Home'?0:e.key==='End'?15:(Number(b.dataset.road)+delta+16)%16;renderRoad();$(`[data-road="${selected}"]`).focus({preventScroll:true});}});
 $('.atlas-search input').addEventListener('input',e=>{query=e.target.value;applyFilter();});root.addEventListener('toggle',()=>onLayout(),true);
 const motionPreference=matchMedia('(prefers-reduced-motion:reduce)'),finePointer=matchMedia('(hover:hover) and (pointer:fine)');
 let activeSurface=null,surfaceBounds=null;
 const motionAllowed=()=>!motionPreference.matches&&!document.hidden&&!document.body.classList.contains('motion-paused');
 function releaseSurface(){if(activeSurface){activeSurface.style.removeProperty('--tilt-x');activeSurface.style.removeProperty('--tilt-y');activeSurface.style.removeProperty('--spot-x');activeSurface.style.removeProperty('--spot-y');activeSurface.classList.remove('tracking');}activeSurface=null;surfaceBounds=null;}
 root.addEventListener('pointerover',e=>{const surface=e.target.closest('.system-row summary');if(surface===activeSurface)return;releaseSurface();if(surface&&finePointer.matches&&motionAllowed()){activeSurface=surface;surfaceBounds=surface.getBoundingClientRect();surface.classList.add('tracking');}});
 root.addEventListener('pointermove',e=>{if(!activeSurface||!surfaceBounds||!motionAllowed())return;const x=Math.max(0,Math.min(1,(e.clientX-surfaceBounds.left)/surfaceBounds.width)),y=Math.max(0,Math.min(1,(e.clientY-surfaceBounds.top)/surfaceBounds.height));activeSurface.style.setProperty('--tilt-x',`${(0.5-y)*8}deg`);activeSurface.style.setProperty('--tilt-y',`${(x-0.5)*5}deg`);activeSurface.style.setProperty('--spot-x',`${x*100}%`);activeSurface.style.setProperty('--spot-y',`${y*100}%`);});
 root.addEventListener('pointerout',e=>{if(activeSurface&&!activeSurface.contains(e.relatedTarget))releaseSurface();});
 addEventListener('scroll',releaseSurface,{passive:true});addEventListener('resize',releaseSurface,{passive:true});
 motionPreference.addEventListener('change',releaseSurface);
 const pauseObserver=new MutationObserver(releaseSurface);pauseObserver.observe(document.body,{attributes:true,attributeFilter:['class']});
 const depthObserver=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('depth-visible',e.isIntersecting)),{threshold:0.08});
 document.addEventListener('visibilitychange',releaseSurface);
 document.addEventListener('ignis:language',e=>translate(e.detail));
 const observer=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('is-near',e.isIntersecting)),{rootMargin:'80px'});observer.observe($('.contract-graph'));
 document.addEventListener('visibilitychange',()=>root.classList.toggle('engine-hidden',document.hidden));
 translate(document.documentElement.lang.startsWith('pt')?'pt':'en');
}
